{"files":[{"path":"index.html","old_sha256":"4535a1b82dbfceeb424bd17b5e32123c648f3b43d4e8113c9041ac8684b1b988","content":"<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Calculator</title>
<style>
  body { font-family: Arial, sans-serif; display: flex; justify-content: center; padding: 20px; background: #f0f0f0; }
  .calculator { background: #222; padding: 16px; border-radius: 12px; width: 280px; box-shadow: 0 4px 12px rgba(0,0,0,.3); }
  #display { width: 100%; box-sizing: border-box; font-size: 24px; padding: 10px; text-align: right; border: none; border-radius: 6px; margin-bottom: 12px; background: #fff; }
  .row { display: flex; gap: 8px; margin-bottom: 8px; }
  .row button { flex: 1; font-size: 20px; padding: 14px 0; border: none; border-radius: 6px; background: #444; color: #fff; cursor: pointer; }
  .row button:hover { background: #555; }
  .row button:active { background: #666; }
  .row .clear { background: #c0392b; }
  .row .clear:hover { background: #d35446; }
</style>
</head>
<body>
<div class="calculator">
  <div class="row"><input id="display" type="text" readonly value="0"></div>
  <div class="row">
    <button data-val="7">7</button>
    <button data-val="8">8</button>
    <button data-val="9">9</button>
    <button data-val="/">/</button>
  </div>
  <div class="row">
    <button data-val="4">4</button>
    <button data-val="5">5</button>
    <button data-val="6">6</button>
    <button data-val="*">*</button>
  </div>
  <div class="row">
    <button data-val="1">1</button>
    <button data-val="2">2</button
    <button data-val="3">3</button>
    <button data-val="-">-</button>
  </div>
  <div class="row">
    <button data-val="0">0</button>
    <button data-val=".">.</button>
    <button data-val="=">=</button>
    <button class="clear" id="clear">Clear</button>
    <button id="sqrt">√</button>
    <button id="square">^2</button>
    <button id="reciprocal">1/x</button>
    <button id="pi">π</button>
    <button id="sin">sin</button>
  </div>
</div>
<script>
(function () {
  var display = document.getElementById('display');
  var clearBtn = document.getElementById('clear');
  var sqrtBtn = document.getElementById('sqrt');
  var squareBtn = document.getElementById('square');
  var reciprocalBtn = document.getElementById('reciprocal');
  var sinBtn = document.getElementById('sin');
  var piBtn = document.getElementById('pi');
  var buttons = document.querySelectorAll('.row button[data-val]');

  function showError() {
    display.value = 'Error';
  }

  function calculate() {
    var expr = display.value;
    if (expr === 'Error' || expr === '' || expr === '0') return;
    // Replace the display dot with a JS-safe form; keep as-is since '.' is valid in JS numbers.
    var result;
    try {
      result = Function('return (' + expr + ')')();
    } catch (e) {
      result = undefined;
    }
    if (result === undefined || result === null || isNaN(result) || !isFinite(result)) {
      showError();
    } else {
      display.value = String(result);
    }
  }

  function sqrt() {
    var val = display.value;
    if (val === 'Error' || val === '') return;
    var result;
    try {
      result = Math.sqrt(parseFloat(val));
    } catch (e) {
      result = undefined;
    }
    if (result === undefined || result === null || isNaN(result) || !isFinite(result)) {
      showError();
    } else {
      display.value = String(result);
    }
  }

  function square() {
    var val = display.value;
    if (val === 'Error' || val === '') return;
    var result;
    try {
      result = Math.pow(parseFloat(val), 2);
    } catch (e) {
      result = undefined;
    }
    if (result === undefined || result === null || isNaN(result) || !isFinite(result)) {
      showError();
    } else {
      display.value = String(result);
    }
  }

  function reciprocal() {
    var val = display.value;
    if (val === 'Error' || val === '') return;
    var result;
    try {
      result = 1 / parseFloat(val);
    } catch (e) {
      result = undefined;
    }
    if (result === undefined || result === null || isNaN(result) || !isFinite(result)) {
      showError();
    } else {
      display.value = String(result);
    }
  }

  function sin() {
    var val = display.value;
    if (val === 'Error' || val === '') return;
    var result;
    try {
      result = Math.sin(parseFloat(val));
    } catch (e) {
      result = undefined;
    }
    if (result === undefined || result === null || isNaN(result) || !isFinite(result)) {
      showError();
    } else {
      display.value = String(result);
    }
  }

  function press(val) {
    if (display.value === 'Error') display.value = '0';
    if (val === '=') {
      calculate();
    } else {
      if (display.value === '0' && val !== '.') display.value = val;
      else display.value += val;
    }
  }

  for (var i = 0; i < buttons.length; i++) {
    (function (btn) {
      btn.addEventListener('click', function () { press(btn.getAttribute('data-val')); });
    })(buttons[i]);
  }

  clearBtn.addEventListener('click', function () { display.value = '0'; });
  sqrtBtn.addEventListener('click', sqrt);
  squareBtn.addEventListener('click', square);
  reciprocalBtn.addEventListener('click', reciprocal);
  sinBtn.addEventListener('click', sin);
  piBtn.addEventListener('click', function () { display.value = String(Math.PI); });
})();
</script>
</body>
</html>
"}]}
